// Đánh giá trạng thái phản hồi của hệ thống
const resp = $json;
const checkTime = new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

let isAlive = true;
let errorReason = '';

if (resp.error) {
  isAlive = false;
  errorReason = resp.error.message || 'Mất kết nối hoặc timeout quá 8 giây';
} else if (resp.statusCode && resp.statusCode >= 400) {
  isAlive = false;
  errorReason = 'Mã phản hồi HTTP lỗi: ' + resp.statusCode;
}

return [{
  json: {
    isAlive: isAlive,
    service: 'Đất Phú Speed POS & API Gateway',
    url: 'https://datphu-backend.vercel.app/speed-pos.html',
    checkTime: checkTime,
    errorReason: errorReason
  }
}];
